window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0aacf56aaf492470"]={"versions": [{"id": "FIG-0aacf56aaf492470", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation der Übergangslogik von DTC-Statusbit 5 (<code>TestFailedSinceLastClear</code>) gemäß ISO 14229-1 innerhalb des AUTOSAR Diagnostic Event Managers (<code>Dem</code>), angesiedelt in den System Services der Basic Software (BSW).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände:</strong>\n<ul class=\"fig-list\"><li><code>Initial state</code>: Pseudozustand / Startzustand für Bit 5.\n</li><li><code>TestFailedSinceLastClear = FALSE</code>: Zustand bei zurückgesetztem Bit 5 (kein Fehlereintrag seit dem letzten Löschen).\n</li><li><code>TestFailedSinceLastClear = TRUE</code>: Zustand bei gesetztem Bit 5 (mindestens ein Fehler aufgetreten seit dem letzten Löschen).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Service-Aufrufe:</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus</code> / <code>Dem_ReportErrorStatus</code> mit Parametern <code>EventId</code> und <code>EventStatus</code> (<code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>).\n</li><li><code>Dem_&lt;...&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code> zum Löschen von Diagnose-Informationen.\n</li></ul>\n</li><li><strong>Interne Ereignisse &amp; Bedingungen:</strong>\n<ul class=\"fig-list\"><li><code>AgingCriteriaFulfilled</code> (optional, referenziert <code>[SWS_Dem_00498]</code>).\n</li><li><code>FaultRecordOverwritten</code> (optional, referenziert <code>[SWS_Dem_00409]</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung:</strong> Übergang vom <code>Initial state</code> nach <code>TestFailedSinceLastClear = FALSE</code>.\n</li><li><strong>Selbsttransition in FALSE:</strong> Ein Statusreport mit <code>DEM_EVENT_STATUS_PASSED</code> via <code>Dem_SetEventStatus</code> oder <code>Dem_ReportErrorStatus</code> belässt Bit 5 im Zustand <code>FALSE</code>.\n</li><li><strong>Fehlereintritt (FALSE -&gt; TRUE):</strong> Der Empfang von <code>EventStatus = DEM_EVENT_STATUS_FAILED</code> via <code>Dem_[SetEvent|ReportError]Status</code> (Fußnote/Bedingungsreferenz <code>[A]</code>) schaltet Bit 5 auf <code>TRUE</code>.\n</li><li><strong>Selbsttransition in TRUE:</strong> Weitere Statusmeldungen mit <code>DEM_EVENT_STATUS_FAILED</code> oder <code>DEM_EVENT_STATUS_PASSED</code> halten Bit 5 im Zustand <code>TRUE</code>.\n</li><li><strong>Rücksetzen (TRUE -&gt; FALSE):</strong> Der Übergang zurück nach <code>FALSE</code> erfolgt durch mindestens eine der folgenden Bedingungen:\n<ul class=\"fig-list\"><li>Aufruf von <code>Dem_&lt;...&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code> (<code>[SWS_Dem_00385]</code>),\n</li><li>Erfüllung der Alterungskriterien (<code>[SWS_Dem_00498] AgingCriteriaFulfilled</code>, optional),\n</li><li>Überschreiben des Fehlereintrags im Ereignisspeicher (<code>[SWS_Dem_00409] FaultRecordOverwritten</code>, optional).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Definiert die normative Implementierungslogik für Bit 5 des UDS-DTC-Status-Bytes (<code>TestFailedSinceLastClear</code>).\n</li><li>Gemäß ISO 14229-1 bleibt Bit 5 nach einem aufgetretenen Fehler über Fahrzyklen hinweg gesetzt, bis ein explizites Löschen (<code>ClearDTC</code>) stattfindet oder konfigurierte Alterungs- bzw. Verdrängungsmechanismen (<code>AgingCriteriaFulfilled</code>, <code>FaultRecordOverwritten</code>) greifen.\n</li><li>Ereignismeldungen mit Status <code>PASSED</code> setzen das Bit nicht zurück, wenn es bereits auf <code>TRUE</code> steht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-aaa933ad0911e475", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Spezifikation der Übergangslogik von DTC-Statusbit 5 (<code>TestFailedSinceLastClear</code>) gemäß ISO 14229-1 innerhalb des AUTOSAR Diagnostic Event Managers (<code>Dem</code>), angesiedelt in den System Services der Basic Software (BSW).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände:</strong>\n<ul class=\"fig-list\"><li><code>Initial state</code>: Pseudozustand / Startzustand für Bit 5.\n</li><li><code>TestFailedSinceLastClear = FALSE</code>: Zustand bei zurückgesetztem Bit 5 (kein Fehlereintrag seit dem letzten Löschen).\n</li><li><code>TestFailedSinceLastClear = TRUE</code>: Zustand bei gesetztem Bit 5 (mindestens ein Fehler aufgetreten seit dem letzten Löschen).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Service-Aufrufe:</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus</code> / <code>Dem_ReportErrorStatus</code> mit Parametern <code>EventId</code> und <code>EventStatus</code> (<code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>).\n</li><li><code>Dem_&lt;...&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code> zum Löschen von Diagnose-Informationen.\n</li></ul>\n</li><li><strong>Interne Ereignisse &amp; Bedingungen:</strong>\n<ul class=\"fig-list\"><li><code>AgingCriteriaFulfilled</code> (optional, referenziert <code>[SWS_Dem_00498]</code>).\n</li><li><code>FaultRecordOverwritten</code> (optional, referenziert <code>[SWS_Dem_00409]</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung:</strong> Übergang vom <code>Initial state</code> nach <code>TestFailedSinceLastClear = FALSE</code>.\n</li><li><strong>Selbsttransition in FALSE:</strong> Ein Statusreport mit <code>DEM_EVENT_STATUS_PASSED</code> via <code>Dem_SetEventStatus</code> oder <code>Dem_ReportErrorStatus</code> belässt Bit 5 im Zustand <code>FALSE</code>.\n</li><li><strong>Fehlereintritt (FALSE -&gt; TRUE):</strong> Der Empfang von <code>EventStatus = DEM_EVENT_STATUS_FAILED</code> via <code>Dem_[SetEvent|ReportError]Status</code> (Fußnote/Bedingungsreferenz <code>[A]</code>) schaltet Bit 5 auf <code>TRUE</code>.\n</li><li><strong>Selbsttransition in TRUE:</strong> Weitere Statusmeldungen mit <code>DEM_EVENT_STATUS_FAILED</code> oder <code>DEM_EVENT_STATUS_PASSED</code> halten Bit 5 im Zustand <code>TRUE</code>.\n</li><li><strong>Rücksetzen (TRUE -&gt; FALSE):</strong> Der Übergang zurück nach <code>FALSE</code> erfolgt durch mindestens eine der folgenden Bedingungen:\n<ul class=\"fig-list\"><li>Aufruf von <code>Dem_&lt;...&gt;ClearDTC(DTC, DTCFormat, DTCOrigin)</code> (<code>[SWS_Dem_00385]</code>),\n</li><li>Erfüllung der Alterungskriterien (<code>[SWS_Dem_00498] AgingCriteriaFulfilled</code>, optional),\n</li><li>Überschreiben des Fehlereintrags im Ereignisspeicher (<code>[SWS_Dem_00409] FaultRecordOverwritten</code>, optional).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Definiert die normative Implementierungslogik für Bit 5 des UDS-DTC-Status-Bytes (<code>TestFailedSinceLastClear</code>).\n</li><li>Gemäß ISO 14229-1 bleibt Bit 5 nach einem aufgetretenen Fehler über Fahrzyklen hinweg gesetzt, bis ein explizites Löschen (<code>ClearDTC</code>) stattfindet oder konfigurierte Alterungs- bzw. Verdrängungsmechanismen (<code>AgingCriteriaFulfilled</code>, <code>FaultRecordOverwritten</code>) greifen.\n</li><li>Ereignismeldungen mit Status <code>PASSED</code> setzen das Bit nicht zurück, wenn es bereits auf <code>TRUE</code> steht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0aacf56aaf492470", "to": "FIG-aaa933ad0911e475", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
